import {useMutation, useQueryClient} from '@github-ui/react-query'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

import type {CreateSavedViewResponse, DuplicateSavedViewVariables} from '../components/views/types'
import {LABELS} from '../constants/labels'
import {parseFetchErrorMessage, SAVED_VIEW_QUERY_KEY, SAVED_VIEWS_QUERY_KEY} from '../queries/saved-views'

interface UseDuplicateSavedViewMutationOptions {
  owner: string
  repo: string
}

export function useDuplicateSavedViewMutation({owner, repo}: UseDuplicateSavedViewMutationOptions) {
  const queryClient = useQueryClient()
  const {addToast} = useToastContext()

  return useMutation<CreateSavedViewResponse, Error, DuplicateSavedViewVariables>({
    mutationFn: async ({view, name}) => {
      const response = await verifiedFetchJSON(`/${owner}/${repo}/issues/views.json`, {
        method: 'POST',
        body: {
          name,
          query: view.query,
          description: view.description ?? undefined,
          icon: view.icon,
          color: view.color,
          source: 'duplicate',
        },
      })
      if (!response.ok) {
        throw new Error(await parseFetchErrorMessage(response, `Failed to duplicate view (${response.status})`))
      }
      return (await response.json()) as CreateSavedViewResponse
    },
    onSuccess: ({savedView}) => {
      queryClient.setQueryData([SAVED_VIEW_QUERY_KEY, owner, repo, String(savedView.id)] as const, {savedView})
      void queryClient.invalidateQueries({queryKey: [SAVED_VIEWS_QUERY_KEY, owner, repo]})
    },
    onError: () => {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({type: 'error', message: LABELS.views.duplicateError})
    },
  })
}
